SELECT MAX(fare_amount) FROM trips 
JOIN zones ON trips.pu_location_id = zones.location_id
WHERE borough = 'Brooklyn' AND EXTRACT(DAYOFWEEK FROM pickup_datetime) = 2 AND passenger_count >= 10;

